const express = require('express');
const { z } = require('zod');
const { TenantRoutingEngine, TenantAdminCheck } = require('../services/dns');

const app = express();
app.use(express.json());

const domainConfigSchema = z.object({
  tenantId: z.string().uuid(),
  customDomain: z.string().regex(/^[a-z0-9.-]+\.[a-z]{2,}$/i),
  routingTarget: z.string().ip({ version: 'v4' })
});

const validateDomainConfig = (req, res, next) => {
  const parsed = domainConfigSchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: parsed.error.issues });
  }
  req.domainData = parsed.data;
  next();
};

app.patch('/api/saas/tenant/domains', validateDomainConfig, async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { tenantId, customDomain, routingTarget } = req.domainData;

  // Verify caller's authenticated tenant matches the requested tenant ID
  if (req.user.tenantId !== tenantId) {
    return res.status(403).json({ error: 'Access denied: cannot modify domain routing of another tenant' });
  }

  const isAdmin = await TenantAdminCheck.isTenantAdmin(req.user.id, tenantId);
  if (!isAdmin) {
    return res.status(403).json({ error: 'Access denied: tenant administrative rights required' });
  }

  await TenantRoutingEngine.updateDomainMapping(tenantId, {
    customDomain,
    routingTarget,
    updatedAt: new Date()
  });

  res.json({ status: 'CONFIGURED', tenantId, customDomain });
});

app.listen(7005);
